<?php require_once __DIR__.'/_base.php'; $title='Reports'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $completed=$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Completed'")->fetchColumn();$cancelled=$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Cancelled'")->fetchColumn();$rating=$pdo->query('SELECT COALESCE(AVG(rating),0) FROM ratings')->fetchColumn();$resolved=$pdo->query("SELECT COUNT(*) FROM complaints WHERE status='Resolved'")->fetchColumn();$value=$pdo->query('SELECT COALESCE(SUM(charges),0) FROM bookings')->fetchColumn();?><h2>Reports & Analytics</h2><div class="row g-3"><div class="col-md-3"><div class="stat-card"><b>Completed bookings</b><div class="display-6"><?=$completed?></div></div></div><div class="col-md-3"><div class="stat-card"><b>Cancelled bookings</b><div class="display-6"><?=$cancelled?></div></div></div><div class="col-md-3"><div class="stat-card"><b>Average rating</b><div class="display-6"><?=number_format($rating,2)?></div></div></div><div class="col-md-3"><div class="stat-card"><b>Resolved complaints</b><div class="display-6"><?=$resolved?></div></div></div></div><div class="service-card p-4 mt-4"><h4>Total booking value</h4><div class="display-5 text-success">PKR <?=number_format($value,2)?></div><p class="text-secondary">This is the recorded value of bookings, not proof of money transferred through AASRA.</p></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>